function qaPreviewChips(){return `<div class="row wrap"><span class="small muted">状态预览</span>${['正常','异常','空'].map(qaP=>`<button class="chip ${qaState.preview===qaP?'on':''}" aria-pressed="${qaState.preview===qaP}" onclick="qaPreview('${qaP}')">${qaP}</button>`).join('')}</div>`;}
function qaCriteria(qaId){return qaId==='BIL-145'?[['C1','当财务角色导出时，系统应允许导出','权限用例'],['C2','当审计员导出时，系统应按已确认权限处理','待补全'],['C3','导出文件应隐藏客户手机号','字段断言']]:[['C1','当你导出账单时，系统应生成可打开的 CSV','冻结用例：金额两位小数与列顺序'],['C2','当你在桌面与手机查看界面时，布局应对齐且无溢出','视觉：900×900 与 420×800'],['C3','当你取消导出时，系统应恢复按钮并保留账期','交互：取消后重新导出']];}
