const qaEscapes=[{id:'穿透-17',project:'p1',template:'界面模板',wi:'BIL-142',stage:'人 L3',summary:'窄视口确认按钮溢出',layer:'自动视觉与产品验收均放行（第 2 轮）',learning:'已写入测试与验收 Agent 的经验记忆；已加入模板评测集',state:'完成'},{id:'穿透-18',project:'p2',template:'接口模板',wi:'CON-80',stage:'甲方 L4',summary:'跨月时区边界对账金额错误',layer:'自动检查、测试 Agent、产品验收均放行（第 1 轮）',learning:'经验记忆写入成功；模板评测集写入重试中（第 2/5 次）',state:'重试中'}];
function qaFilter(qaKey,qaValue){qaState[qaKey]=qaValue;route();}
PAGES['escapes']=()=>{const qaRows=qaEscapes.filter(qaE=>(qaState.project==='全部'||qaState.project===qaE.project)&&(qaState.template==='全部'||qaState.template===qaE.template));return head('团队质量','穿透记录与学习','人或甲方发现内部已放行的问题，回流到测试、验收经验与模板评测集。')+`<div class="grid g12"><div class="c12">${card('按项目 / 模板筛选',`<div class="row wrap"><label class="stack">项目<select style="${qaStyle}" onchange="qaFilter('project',this.value)">${[['全部','全部项目'],['p1','账单中心'],['p2','商户控制台']].map(qaO=>`<option value="${qaO[0]}" ${qaState.project===qaO[0]?'selected':''}>${qaO[1]}</option>`).join('')}</select></label><label class="stack">模板<select style="${qaStyle}" onchange="qaFilter('template',this.value)">${['全部','界面模板','接口模板'].map(qaO=>`<option ${qaState.template===qaO?'selected':''}>${qaO}</option>`).join('')}</select></label></div>`)}</div><div class="c4">${card('团队穿透率趋势 · 近四周',spark([12,8,6,4])+qaTable(['周','问题数 / 进入 L3 项数','穿透率'],[['第 1 周','3 / 25','12%'],['第 2 周','2 / 25','8%'],['第 3 周','3 / 50','6%'],['第 4 周','2 / 50','4%']])+'<p class="small muted">团队固定窗口样例；列表筛选不改变趋势口径。分子含 L3 / L4 发现的内部已放行问题数。</p>')}</div><div class="c8">${card('穿透明细',qaRows.length?qaTable(['工作项 / 发现者','内部放行层与问题','学习动作'],qaRows.map(qaE=>[`<a href="#/internal-qa/${qaE.wi}">${qaE.wi}</a><p>${qaE.stage} · ${qaE.id}</p><span class="small muted">${qaE.template}</span>`,`${qaE.summary}<p class="small muted">${qaE.layer}</p>`,`${qaBadge(qaE.state,qaE.state==='完成'?'ok':'warn')}<p>${qaE.learning}</p>`])):'<div class="empty">所选项目与模板暂无穿透记录。</div>')}</div><div class="c12">${card('学习闭环与责任',qaKV([['执行方','穿透学习任务是唯一写入方，按事件幂等回流'],['经验类型','测试与产品验收 Agent 的经验记忆，不自动变成规则记忆'],['评测集','携带问题摘要、来源工作项、证据引用与预期；维护者可停用用例'],['失败处理','最多重试 5 次；仍失败则标记学习失败并通知团队所有者'],['责任人',who('morgan')]]))}</div></div>`;};
PAGES['exception']=qaArg=>{const qaId=qaArg||'EX-7';if(qaId!=='EX-7')return head('容差例外','未找到例外报告','请检查编号。')+card('无记录','<div class="empty">暂无此例外。</div>');const qaE=qaState.exceptions[qaId];return head('可靠性闭环 · EX-7','容差例外','BIL-142 · 按预测越界暂停执行，禁止静默延期。',qaBadge(qaE?'已决定：'+qaE.decision:'例外待决定',qaE?'info':'warn'))+`<div class="grid g12"><div class="c8 stack">${card('预测越界',qaTable(['维度','基准 / 容差','已用','预测 / 上限','判断'],[['时间','240 分钟 / 20%','180 分钟','320 / 288 分钟','预测越界'],['成本','12 美元 / 10%','8 美元','14 / 13.2 美元','预测越界'],['范围','新增标准容差 0 条','新增 0 条','新增 1 / 0 条','预测越界']])+'<p class="small muted">每 15 分钟预测；时间为已用墙钟 + 同类剩余中位数，成本为已用 + 剩余预测，范围按新增验收标准数。</p>')}${card('现状 / 选项 / 建议',qaKV([['现状','冻结测试通过，窄视口重排预计需额外 80 分钟；执行已暂停'],['继续','扩充时间与成本容差；恢复原执行，负责人承担新预算'],['重新塑形','回到草稿并建立范围变更记录；需求升版本，重做就绪与冻结'],['暂停','转为阻塞（暂停），保留产物与证据'],['终止','取消工作项与活跃执行；已发生费用和外部副作用不回滚'],['建议','重新塑形，延后新增标准，保留已确认范围']]))}</div><div class="c4 stack">${card('决定资格',qaKV([['决定人',who('morgan')],['权限','仅具备例外决定权限的人类；不可委托'],['Agent','主管可补充报告，不能决定；助理仅能起草'],['认证','所有决定需重新认证；本原型仅演示确认，不验证真实身份']]))}${card('例外决定',`<div class="note danger">决定会改变预算、范围或执行状态。终止无法回滚已产生的副作用；需重新认证。</div><div class="stack" style="margin-top:12px">${['继续','重新塑形','暂停','终止'].map(qaD=>qaButton(qaD,`qaExceptionDecision('${qaD}')`,'danger',!!qaE,'报告已裁决，不能重复决定')).join('')}</div>${qaE?`<p>${qaEsc(qaE.reason)}；结果：${qaEsc(qaE.result)}</p>`:''}`)}</div></div>`;};
function qaExceptionDecision(qaDecision){qaModal('例外决定：'+qaDecision,'<div class="note danger">需重新认证。继续恢复执行；重新塑形回到草稿；暂停转为阻塞；终止取消工作项且不回滚副作用。</div>'+qaReasonField()+(qaDecision==='继续'?qaField('新时间预算（分钟，必填）','qaAppetite','360','number')+qaField('新成本容差（百分比）','qaCostTolerance','20','number')+qaField('新范围容差（新增标准条数）','qaScopeTolerance','1','number'):'')+'<label class="row"><input type="checkbox" id="qaReauth">你确认模拟重新认证（非真实身份验证）</label>',qaButton('确认决定',`qaExceptionSubmit('${qaDecision}')`,'danger'));}
function qaExceptionSubmit(qaDecision){const qaR=document.getElementById('qaReason').value.trim();if(!qaR)return qaError('请填写决定原因');if(!document.getElementById('qaReauth').checked)return qaError('请完成模拟重新认证确认');if(qaState.exceptions['EX-7'])return qaError('报告已裁决');let qaNew=null;if(qaDecision==='继续'){const qaMinutes=Number(document.getElementById('qaAppetite').value),qaCost=Number(document.getElementById('qaCostTolerance').value),qaScope=Number(document.getElementById('qaScopeTolerance').value);if(!Number.isFinite(qaMinutes)||qaMinutes<=0||!Number.isFinite(qaCost)||qaCost<0||!Number.isInteger(qaScope)||qaScope<0)return qaError('请输入有效的新预算与非负容差');if(qaMinutes*1.2<320||12*(1+qaCost/100)<14||qaScope<1)return qaError('新预算 / 容差仍低于当前预测，请调整');qaNew={minutes:qaMinutes,costTolerance:qaCost,scopeTolerance:qaScope};}qaState.exceptions['EX-7']={decision:qaDecision,reason:qaR,budget:qaNew,result:({'继续':`恢复原状态与执行；新时间预算 ${qaNew?qaNew.minutes:0} 分钟`,'重新塑形':'草稿；已记录范围变更（演示）','暂停':'阻塞（暂停）','终止':'已取消'})[qaDecision]};closeModal();route();toast('例外决定已记录（演示）');}
function qaAndon(qaId){if(!qaWork(qaId))return toast('未找到工作项');if(qaState.stops[qaId])return toast('该工作项已有停线记录，未重复创建');qaModal('拉 Andon 停线 · '+qaEsc(qaId),'<div class="note danger">停线会暂停活跃执行并阻塞下游依赖；需重新认证。Agent 也能停线，但只有人类负责人 / 交付负责人能解除。</div>'+qaReasonField()+qaField('证据引用（Agent 停线时必填）','qaEvidence')+'<label class="stack small">拉绳主体<select id="qaPullActor" style="'+qaStyle+'"><option value="human">你 · 人类成员</option><option value="agent">执行 Agent</option></select></label>'+qaKV([['影响的下游依赖','BIL-144 接口文档；BIL-146 文件名账期（依赖关系示例）'],['通知对象',who('morgan')+' · 人类负责人 / 交付负责人'],['恢复条件','负责人确认处置后恢复原状态与执行，移除下游停线阻塞']])+'<label class="row"><input id="qaReauth" type="checkbox">你确认模拟重新认证（非真实身份验证）</label>',qaButton('确认停线',`qaAndonSubmit('${qaId}')`,'danger'));}
function qaAndonSubmit(qaId){const qaR=document.getElementById('qaReason').value.trim(),qaActor=document.getElementById('qaPullActor').value,qaEvidence=document.getElementById('qaEvidence').value.trim();if(qaR.length<10)return qaError('停线原因至少 10 个字');if(qaActor==='agent'&&!qaEvidence)return qaError('Agent 停线必须附证据引用');if(!document.getElementById('qaReauth').checked)return qaError('请完成模拟重新认证确认');if(!qaState.stops[qaId])qaState.stops[qaId]={reason:qaR,actor:qaActor,evidence:qaEvidence};closeModal();route();toast('已停线：下游依赖已阻塞，通知负责人（演示）');}
TITLES['readiness']='就绪检查';NAVPARENT['readiness']='work';
TITLES['plan-review']='计划审批';NAVPARENT['plan-review']='work';
